<?php $editing=!empty($recipe['id']);?>
<div class="form-page"><div class="section-head"><div><p class="eyebrow"><?=$editing?'TUNE THE FLAVOR':'A NEW FAVORITE'?></p><h1><?=$editing?'Edit recipe':'Create a recipe'?></h1></div></div>
<div id="recipe-source-data" data-url="<?=e($recipe['source_url']??'')?>" data-name="<?=e($recipe['source_name']??'')?>" data-author="<?=e($recipe['source_author']??'')?>"></div><?php $viewer=App\Auth::user();if(!$editing&&in_array($viewer['role']??'', ['admin','superadmin'],true)):?><section class="panel recipe-importer"><p class="eyebrow">IMPORT A RECIPE</p><form id="recipe-import" action="/recipes/import" method="post" class="import-row"><?=csrf()?><label>Recipe URL<input type="url" name="url" required placeholder="https://www.seriouseats.com/…"></label><button>Import</button></form><p class="muted import-status">Currently supports Serious Eats. Images and surrounding article content are not imported.</p></section><?php endif?>
<form method="post" action="<?=$action?>" enctype="multipart/form-data" class="recipe-form"><?=csrf()?><?php if(!$editing&&!empty($recipe['forked_from_id'])):?><input type="hidden" name="forked_from_id" value="<?=e($recipe['forked_from_id'])?>"><?php endif?><div class="panel stack"><label>Recipe title<input name="title" value="<?=e($recipe['title'])?>" required maxlength="180" placeholder="Grandma’s cinnamon rolls"></label><label>Short description<textarea name="summary" rows="2" placeholder="What makes this one special?"><?=e($recipe['summary'])?></textarea></label><label>Ingredients <small>One per line works beautifully</small><textarea name="ingredients" rows="9" required placeholder="2 cups flour&#10;1 tsp salt"><?=e($recipe['ingredients'])?></textarea></label><label>Instructions<textarea name="instructions" rows="12" required placeholder="1. Preheat the oven…"><?=e($recipe['instructions'])?></textarea></label><label>Notes<textarea name="notes" rows="4" placeholder="Substitutions, serving ideas, happy accidents…"><?=e($recipe['notes'])?></textarea></label></div>
<aside class="panel stack"><label class="toggle"><input type="checkbox" name="is_public" value="1" <?=$recipe['is_public']?'checked':''?>><span></span><div><b>Public recipe</b><small>Anyone can discover and make their own version.</small></div></label>
<label>Cuisine<select name="cuisine_id"><option value="">Not specified</option><?php foreach($cuisines as $c):?><?php if($c['is_active']||(int)($recipe['cuisine_id']??0)===(int)$c['id']):?><option value="<?=$c['id']?>" <?=(int)($recipe['cuisine_id']??0)===(int)$c['id']?'selected':''?>><?=e($c['name'])?><?=$c['is_active']?'':' (archived)'?></option><?php endif?><?php endforeach?></select></label>
<fieldset class="tag-picker"><legend>Tags</legend><div class="tag-options"><?php foreach($tags as $tag):?><?php $chosen=in_array((int)$tag['id'],$selectedTags,true);if($tag['is_active']||$chosen):?><label><input type="checkbox" name="tags[]" value="<?=$tag['id']?>" <?=$chosen?'checked':''?>><span><?=e($tag['name'])?><?=$tag['is_active']?'':' (archived)'?></span></label><?php endif?><?php endforeach?></div></fieldset>
<label>Photos <small>The first is the search thumbnail</small><input type="file" name="photos[]" accept="image/jpeg,image/png,image/webp,image/gif" multiple></label><?php if(!empty($photos)):?><div class="mini-gallery photo-editor"><?php foreach($photos as $i=>$p):?><div class="photo-editor-item"><img src="/uploads/<?=e($p['filename'])?>" alt=""><?php if($editing):?><div class="photo-actions"><label class="photo-action photo-choice" title="Use as thumbnail"><input class="photo-control" type="radio" name="primary_photo" value="<?=$p['id']?>" <?=$i===0?'checked':''?>><span aria-hidden="true">★</span><span class="sr-only">Use this image as the thumbnail</span></label><label class="photo-action photo-remove" title="Remove image"><input class="photo-control" type="checkbox" name="remove_photos[]" value="<?=$p['id']?>"><span aria-hidden="true">×</span><span class="sr-only">Remove this image when the recipe is saved</span></label></div><span class="cover-badge">Cover</span><span class="remove-badge">Will remove</span><?php endif?></div><?php endforeach?></div><?php endif?><button>Save recipe</button><a class="button secondary" href="<?=$editing?'/recipes/'.$recipe['id']:'/'?>">Cancel</a></aside></form></div>
